"""Ready-made mini-series seasons (Persian): a complete season slate (hook, logline, escalation, twist, cliffhanger, the answer to the previous cliffhanger, the threads opened
and closed) with ORIGINAL recurring characters, so the owner can start a channel from real episodes even when no text model is reachable (the season planner falls back to
these instead of placeholder text), and a language model has a worked example of the form.

Only the FORMAT of the stick-figure survival / escape / comedy genre is used (see conventions.py): short episodes, a hook in the first seconds, one place and one goal per
episode, a cliffhanger in the last seconds that the next episode answers. No character, story, title, catchphrase or joke of any existing channel appears here.
`tests/test_story_templates.py` runs every season through `planner.validate` (no errors, no warnings) and checks the cast appears.

The brand season (`chagher_coaches`) is a comedy that uses only facts published by the product itself (a draft in under a minute, the coach's own standing instruction, the
branded PDF, the final decision is the coach's); it promises no result and invents no customer, price or statistic.
"""
from __future__ import annotations

import copy


def E(n: int, title: str, hook: str, logline: str, escalation: str, twist: str, cliff: str, payoff: str, who: list[str], where: str, opens=(), closes=()) -> dict:
    return {"number": n, "title": title, "hook": hook, "logline": logline, "escalation": escalation, "twist": twist, "cliffhanger": cliff, "payoff_of_previous": payoff,
            "characters": list(who), "location": where, "opens": list(opens), "closes": list(closes)}


def M(name: str, role: str, marker: str, catchphrase: str, appearance: str, **spec) -> dict:
    return {"name": name, "role": role, "marker": marker, "catchphrase": catchphrase, "appearance": appearance, "spec": spec}


