TEMPLATES: list[dict] = [SILENT_CITY, TOWER, CHAGHER_COACHES]
BY_KEY: dict[str, dict] = {t["key"]: t for t in TEMPLATES}


def get(key: str) -> dict | None:
    return BY_KEY.get(key)


def for_genre(genre: str) -> dict | None:
    for t in TEMPLATES:
        if t["genre"] == genre and not t["key"].startswith("chagher"):
            return t
    return None


def plan_of(template: dict) -> dict:
    """The template as a season-planner answer that `services.apply_season_plan` accepts."""
    rows = copy.deepcopy(template["episodes"])
    for r in rows:
        r["runtime_sec"] = template["runtime_sec"]
    return {"season_title": template["season_title"], "season_arc": template["season_arc"], "episodes": rows}


def listing() -> list[dict]:
    return [{"key": t["key"], "genre": t["genre"], "title_fa": t["title_fa"], "title_en": t["title_en"], "blurb_fa": t["blurb_fa"], "blurb_en": t["blurb_en"], "episodes": len(t["episodes"]),
             "runtime_sec": t["runtime_sec"], "cast": [{"name": c["name"], "role": c["role"], "marker": c["marker"], "limb": c["spec"].get("limb_colour", "#1f2430")} for c in t["cast"]]}
            for t in TEMPLATES]
